CREATE OR REPLACE FUNCTION public.fn_autoclear_featured_on_visibility_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF NEW.visibility <> 'public' THEN
    NEW.is_featured_on_landing := false;
    NEW.featured_nominated_by := NULL;
    NEW.featured_nominated_at := NULL;
    NEW.featured_approved_by := NULL;
    NEW.featured_approved_at := NULL;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_badge_check_flashcards()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_total_flashcards INTEGER;
  v_subject_count    INTEGER;
BEGIN
  -- Read counter updated by trg_aaa_counter_flashcards (fired first)
  SELECT total_flashcards
  INTO v_total_flashcards
  FROM user_stats
  WHERE user_id = NEW.user_id;

  -- Memory Architect: 10 flashcards total
  IF v_total_flashcards >= 10 THEN
    PERFORM award_badge(NEW.user_id, 'memory_architect');
  END IF;

  -- Deck Builder: 50 flashcards total
  IF v_total_flashcards >= 50 THEN
    PERFORM award_badge(NEW.user_id, 'deck_builder');
  END IF;

  -- Subject Expert: 20 flashcards in the SAME subject
  -- Only runs COUNT for the specific subject_id of the new card.
  IF NEW.subject_id IS NOT NULL THEN
    SELECT COUNT(*)
    INTO v_subject_count
    FROM flashcards
    WHERE user_id   = NEW.user_id
      AND subject_id = NEW.subject_id;

    IF v_subject_count >= 20 THEN
      PERFORM award_badge(NEW.user_id, 'subject_expert');
    END IF;
  END IF;

  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_badge_check_notes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_total_notes INTEGER;
BEGIN
  -- Read counter updated by trg_aaa_counter_notes (fired first)
  SELECT total_notes
  INTO v_total_notes
  FROM user_stats
  WHERE user_id = NEW.user_id;

  -- Digitalizer: first note uploaded
  IF v_total_notes >= 1 THEN
    PERFORM award_badge(NEW.user_id, 'digitalizer');
  END IF;

  -- Prolific Writer: 5 notes
  IF v_total_notes >= 5 THEN
    PERFORM award_badge(NEW.user_id, 'prolific_writer');
  END IF;

  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_guard_flashcard_batch_move()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  o_has  boolean;
  n_has  boolean;
  o_type text;
  o_name text;
  n_type text;
  n_name text;
BEGIN
  IF OLD.batch_id IS NULL OR NEW.batch_id IS NULL THEN
    RAISE EXCEPTION 'MERGE_TARGET_INVALID: cards without a batch cannot be merged or moved into or out of a batch.'
      USING ERRCODE = 'RV601';
  END IF;

  -- Target batch must already exist and be held only by this card's owner (owner data, not auth.uid()).
  IF NOT EXISTS (SELECT 1 FROM public.flashcards f
                  WHERE f.batch_id = NEW.batch_id AND f.user_id = OLD.user_id AND f.id <> OLD.id)
     OR EXISTS (SELECT 1 FROM public.flashcards f
                 WHERE f.batch_id = NEW.batch_id AND f.user_id <> OLD.user_id) THEN
    RAISE EXCEPTION 'MERGE_TARGET_INVALID: cards can only be merged into an existing batch that belongs to the same owner.'
      USING ERRCODE = 'RV601';
  END IF;

  SELECT p.content_source_type, p.content_source_name INTO o_type, o_name
    FROM public.flashcard_batch_provenance p WHERE p.batch_id = OLD.batch_id;
  o_has := FOUND;
  SELECT p.content_source_type, p.content_source_name INTO n_type, n_name
    FROM public.flashcard_batch_provenance p WHERE p.batch_id = NEW.batch_id;
  n_has := FOUND;

  IF o_has <> n_has
     OR (o_has AND (o_type IS DISTINCT FROM n_type OR o_name IS DISTINCT FROM n_name)) THEN
    RAISE EXCEPTION 'MERGE_PROVENANCE_MISMATCH: these batches cannot be merged because their content sources differ (same source type and source name are required, or both must have no source recorded).'
      USING ERRCODE = 'RV601';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_guard_flashcards_is_verified()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF current_user NOT IN ('authenticated', 'anon') THEN
    RETURN NEW;
  END IF;
  IF NEW.is_verified IS TRUE
     AND (TG_OP = 'INSERT' OR OLD.is_verified IS DISTINCT FROM TRUE)
     AND NOT public.is_professor_or_admin() THEN
    RAISE EXCEPTION 'Not permitted: only an educator or admin can mark content verified' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_guard_notes_decks_privileged_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_new jsonb := to_jsonb(NEW);
  v_old jsonb := CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(OLD) ELSE '{}'::jsonb END;
  k text;
BEGIN
  IF current_user NOT IN ('authenticated', 'anon') THEN
    RETURN NEW;
  END IF;
  IF public.is_admin() THEN
    RETURN NEW;
  END IF;

  -- Featured flag: may only be cleared, never set.
  IF (v_new->>'is_featured_on_landing') = 'true' AND (v_old->>'is_featured_on_landing') IS DISTINCT FROM 'true' THEN
    RAISE EXCEPTION 'Not permitted: featuring is decided by curation, not by the content owner' USING ERRCODE = '42501';
  END IF;

  -- Nomination / approval stamps: may only be cleared, never set or changed.
  FOREACH k IN ARRAY ARRAY['featured_nominated_by', 'featured_nominated_at', 'featured_approved_by', 'featured_approved_at'] LOOP
    IF (v_new->>k) IS NOT NULL AND (v_new->>k) IS DISTINCT FROM (v_old->>k) THEN
      RAISE EXCEPTION 'Not permitted: % is set by the curation workflow only', k USING ERRCODE = '42501';
    END IF;
  END LOOP;

  -- Server-maintained counters.
  FOREACH k IN ARRAY ARRAY['upvote_count', 'view_count'] LOOP
    IF v_new ? k THEN
      IF TG_OP = 'INSERT' AND COALESCE((v_new->>k)::int, 0) <> 0 THEN
        RAISE EXCEPTION 'Not permitted: % starts at 0', k USING ERRCODE = '42501';
      END IF;
      IF TG_OP = 'UPDATE' AND (v_new->>k) IS DISTINCT FROM (v_old->>k) THEN
        RAISE EXCEPTION 'Not permitted: % is maintained by the platform', k USING ERRCODE = '42501';
      END IF;
    END IF;
  END LOOP;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_guard_profiles_protected_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  -- Only direct client writes are constrained (see header).
  IF current_user NOT IN ('authenticated', 'anon') THEN
    RETURN NEW;
  END IF;

  IF NEW.id IS DISTINCT FROM OLD.id THEN
    RAISE EXCEPTION 'Not permitted: profiles.id is immutable' USING ERRCODE = '42501';
  END IF;

  IF NEW.role IS DISTINCT FROM OLD.role AND NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Not permitted: only a super admin can change a role' USING ERRCODE = '42501';
  END IF;

  IF (NEW.account_type IS DISTINCT FROM OLD.account_type
      OR NEW.status IS DISTINCT FROM OLD.status
      OR NEW.email IS DISTINCT FROM OLD.email
      OR NEW.access_request_ref IS DISTINCT FROM OLD.access_request_ref)
     AND NOT public.is_admin() THEN
    RAISE EXCEPTION 'Not permitted: account_type, status, email and access_request_ref are managed by admins'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$function$
